from typing import List

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        count = {}

        for i in range(n - k + 1):
            window = nums[i:i + k]
            for x in set(window):
                count[x] = count.get(x, 0) + 1

        ans = -1
        for x, c in count.items():
            if c == 1:
                ans = max(ans, x)

        return ans
